# Simulate processing of the SQL query to calculate retention rates for each month
def calculate_retention_rate(orders_df):
    periods = pd.date_range(end=datetime.today(), periods=6, freq='M')
    retention_data = []

    for period in periods:
        current_period_end = period.replace(day=1) + pd.DateOffset(months=1)
        current_period_start = current_period_end - pd.DateOffset(months=1)
        previous_period_start = current_period_start - pd.DateOffset(months=1)

        current_customers = orders_df[
            (orders_df['OrderDate'] >= previous_period_start.strftime('%Y-%m-%d')) &
            (orders_df['OrderDate'] < current_period_start.strftime('%Y-%m-%d'))
        ]['CustomerID'].unique()

        previous_customers = orders_df[
            (orders_df['OrderDate'] >= (previous_period_start - pd.DateOffset(months=1)).strftime('%Y-%m-%d')) &
            (orders_df['OrderDate'] < previous_period_start.strftime('%Y-%m-%d'))
        ]['CustomerID'].unique()

        if len(previous_customers) > 0:
            retention_rate = (len(set(current_customers) & set(previous_customers)) / len(previous_customers)) * 100
        else:
            retention_rate = 0

        retention_data.append({
            'Month': current_period_start.strftime('%Y-%m'),
            'RetentionRate': retention_rate
        })

    return pd.DataFrame(retention_data)

